//! The core `queryweave` runtime: the types the code generated for root models
//! (`Filters`, `MergePatch`, `MergePatchNullableFields`, `RawValue`) names, and
//! the traits linking the layers (`Filterable` and the role traits).
//! `queryweave-api` and `queryweave-sql` re-export it.
//!
//! Nothing here depends on a database: the generated code describes filters,
//! sorting and writes as data ([`FilterCondition`], [`SortKey`],
//! [`FieldValue`]) and the persistence layer turns that data into queries.
//!
//! The optional `serde` feature (off by default) makes [`Patch`] deserializable,
//! for an API's merge patch types; `queryweave-api`'s `serde` feature enables
//! it.

mod filterable;
mod model_data;
#[cfg(feature = "merge-patch")]
mod patch;
mod raw_value;
mod value;
mod version;

pub use filterable::{
    FilterOptionsOf, Filterable, IntoRootQuery, QueryOf, SortDetailsOf, SortFieldOf,
};
pub use model_data::{Conditions, FieldValues, ModelData, NamesField, SortKeys};
#[cfg(feature = "merge-patch")]
pub use patch::{Patch, PatchField, PatchKind};

/// Not public API: what the code generated by `queryweave-derive` calls.
#[doc(hidden)]
pub mod __private {
    pub use crate::model_data::model_data;
    pub use crate::version::require_version;
}
pub use raw_value::{Boolean, Ordered, RawValue, Text};
pub use value::{FieldValue, FilterCondition, IntoValue, SortKey, Value, ValueKind, ValueType};

/// A type whose data names domain fields the persistence layer maps onto
/// columns.
///
/// They are the fields a generated filter-options model filters on, a query
/// model filters or sorts by, or a `MergePatch` model may write.
///
/// Implemented by the derives; the persistence layer checks at compile time
/// that each field has a column before writing any SQL for the type's data.
pub trait PersistedFields {
    /// The domain fields, once each, in declaration order.
    const FIELD_NAMES: &'static [&'static str];

    /// The value type of each field, in [`FIELD_NAMES`](Self::FIELD_NAMES)
    /// order (the [`IntoValue::TYPE`] of its raw value), for the persistence
    /// layer to check against its column's type at compile time; empty when
    /// unknown, which checks nothing.
    ///
    /// The derives fill it in for a filter-options model and a `MergePatch`
    /// model, whose data carries values; a query model's sort keys carry
    /// none.
    const FIELD_TYPES: &'static [ValueType] = &[];
}

/// The comparison a generated filter field performs against its column.
///
/// Chosen by `#[derive(Filters)]` from the field's `#[filter(...)]` meta; how
/// it is expressed in a query is up to the persistence layer.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FilterOperator {
    /// `lt`: the column is less than the value.
    LessThan,
    /// `eq` (and `bool`): the column equals the value.
    Equal,
    /// `gt`: the column is greater than the value.
    GreaterThan,
    /// `sw`: the column starts with the value.
    StartsWith,
    /// `c`: the column contains the value.
    Contains,
    /// `ew`: the column ends with the value.
    EndsWith,
}

/// How the sorting direction is evaluated. How it is expressed in a query is
/// up to the persistence layer.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum SortDirectionModel {
    /// Sort in ascending order.
    #[default]
    Ascending,
    /// Sort in descending order.
    Descending,
}

#[cfg(feature = "merge-patch")]
/// Detect changes in field values.
pub trait ChangedFields {
    /// Compose a change set of the field names corresponding to field values that have changed.
    fn modified_fields(&self, previous: &Self) -> ChangeSet;
}

#[cfg(feature = "merge-patch")]
/// The names of the fields that changed, e.g. between a model and its
/// merge-patched version.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct ChangeSet {
    fields: std::collections::HashSet<&'static str>,
}

#[cfg(feature = "merge-patch")]
impl ChangeSet {
    /// Whether no field changed.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.fields.is_empty()
    }

    /// Record a field as changed; whether it was not recorded yet.
    pub fn insert(&mut self, field: &'static str) -> bool {
        self.fields.insert(field)
    }

    /// Whether a field was recorded as changed.
    #[must_use]
    pub fn contains(&self, field: &str) -> bool {
        self.fields.contains(field)
    }
}

#[cfg(feature = "merge-patch")]
impl FromIterator<&'static str> for ChangeSet {
    fn from_iter<I: IntoIterator<Item = &'static str>>(fields: I) -> Self {
        Self {
            fields: fields.into_iter().collect(),
        }
    }
}

#[cfg(feature = "merge-patch")]
/// A merge patch model: which of its fields a client may set to `null`
/// (its [`Patch`] fields), as opposed to leaving them out.
///
/// Implemented by `#[derive(MergePatchNullableFields)]`, from each field's
/// [`PatchKind`]. A field that may be cleared is a [`Patch<T>`];
/// `Option<Option<T>>` is not supported, and the derive rejects it.
#[diagnostic::on_unimplemented(
    message = "`{Self}` is not a merge patch model",
    label = "does not derive `MergePatchNullableFields`",
    note = "derive `MergePatchNullableFields` on the merge patch struct; its fields are `Option<T>` (cannot be cleared) or `queryweave::Patch<T>` (can), never `Option<Option<T>>`"
)]
pub trait MergePatchNullableFields {
    /// Whether the field named `field` may be set to `null`.
    fn is_nullable(field: &str) -> bool;
}

#[cfg(feature = "merge-patch")]
/// Which fields of a merge patch struct may be set to `null`, under its own
/// names.
///
/// Implemented for every merge patch model ([`MergePatchNullableFields`]),
/// and by `#[derive(ValidateNonNullable)]` for a struct mirroring one (e.g.
/// an API DTO) or mirroring another mirror (e.g. a gRPC message mirroring
/// the DTO), which asks the struct it mirrors under that struct's names: so
/// mirrors chain, every chain ending at a merge patch model.
#[diagnostic::on_unimplemented(
    message = "`{Self}` is neither a merge patch model nor a struct mirroring one",
    label = "not a merge patch model, nor a mirror of one",
    note = "derive `MergePatchNullableFields` on a merge patch model, or `ValidateNonNullable` on a struct mirroring one"
)]
pub trait NullableFields {
    /// The merge patch model the chain of mirrors ends at (`Self` for a
    /// model). Two structs mirroring each other have none, so they fail to
    /// compile rather than ask each other forever.
    type Root: MergePatchNullableFields;

    /// Whether the field named `field` (as on `Self`) may be set to `null`.
    fn is_nullable(field: &str) -> bool;
}

#[cfg(feature = "merge-patch")]
impl<T: MergePatchNullableFields> NullableFields for T {
    type Root = Self;

    fn is_nullable(field: &str) -> bool {
        <T as MergePatchNullableFields>::is_nullable(field)
    }
}

#[cfg(test)]
mod tests {
    use super::{ChangeSet, SortDirectionModel};

    // A freshly built, empty change set reports empty.
    #[test]
    fn is_empty_is_true_for_a_fresh_change_set() {
        assert!(ChangeSet::default().is_empty());
    }

    // `is_empty` must be false once a change has been recorded (kills the
    // `is_empty`->`true` mutant, which the empty-set case alone cannot catch).
    #[test]
    fn is_empty_is_false_after_a_change_is_recorded() {
        let mut change_set = ChangeSet::default();

        assert!(change_set.insert("test_field"));
        assert!(!change_set.is_empty());
    }

    // Inserting the same field twice reports `false` the second time (kills the
    // `insert`->`true`/`false` mutants).
    #[test]
    fn insert_reports_whether_the_field_was_new() {
        let mut change_set = ChangeSet::default();

        assert!(change_set.insert("test_field"));
        assert!(!change_set.insert("test_field"));
    }

    #[test]
    fn contains_reports_only_the_recorded_fields() {
        let mut change_set = ChangeSet::default();
        _ = change_set.insert("number");

        assert!(change_set.contains("number"));
        assert!(!change_set.contains("value"));
    }

    // Collecting field names records each of them, once.
    #[test]
    fn collecting_records_the_fields() {
        let change_set: ChangeSet = ["number", "value", "number"].into_iter().collect();

        assert!(change_set.contains("number"));
        assert!(change_set.contains("value"));
        assert!(!change_set.contains("client"));
        assert_eq!(change_set, ["value", "number"].into_iter().collect());
    }

    #[test]
    fn sort_direction_defaults_to_ascending() {
        assert_eq!(SortDirectionModel::default(), SortDirectionModel::Ascending);
    }
}
